select
a.device_id,
a.custom_id,
a.device_code,
a.device_name,
a.alias_name,
a.device_type,
a.position_type,
a.model_id,
a.region_path,
a.up_region_id,
a.up_region_name,
a.custom_name,
a.custom_type,
a.status,
a.update_time,
a.create_time
from t_std_device a
where 1 = 1
 and a.device_id = #{deviceId, jdbcType=BIGINT}
 and a.custom_id = #{customId, jdbcType=VARCHAR}
 and a.device_code = #{deviceCode, jdbcType=VARCHAR}
 and a.device_name = #{deviceName, jdbcType=VARCHAR}
 and a.alias_name = #{aliasName, jdbcType=VARCHAR}
 and a.device_type = #{deviceType, jdbcType=INTEGER}
 and a.position_type = #{positionType, jdbcType=VARCHAR}
 and a.model_id = #{modelId, jdbcType=BIGINT}
 and a.region_path = #{regionPath, jdbcType=VARCHAR}
 and a.up_region_id = #{upRegionId, jdbcType=BIGINT}
 and a.up_region_name = #{upRegionName, jdbcType=VARCHAR}
 and a.custom_name = #{customName, jdbcType=VARCHAR}
 and a.custom_type = #{customType, jdbcType=INTEGER}
 and a.status = #{status, jdbcType=INTEGER}
 and a.update_time = #{updateTime, jdbcType=TIMESTAMP}
 and a.create_time = #{createTime, jdbcType=TIMESTAMP}

select
a.device_id ,
a.custom_id ,
a.device_code ,
a.device_name ,
a.alias_name ,
a.device_type ,
h.dict_note as deviceTypeName,
a.position_type ,
a.model_id ,
a.region_path ,
a.up_region_id ,
a.up_region_name ,
a.custom_name ,
a.custom_type ,
a.status ,
a.update_time ,
a.create_time ,
b.device_model,
e.dict_note as deviceModelName,
b.pms_type,
b.pms_id,
b.device_vendor,
f.dict_note deviceVendorName,
b.production_date ,
b.used_time,
b.disable_date,
b.last_maintenance,
b.maintenance_count,
b.organization,
b.department,
b.responsible_person,
b.latitude,
b.longitude,
b.ip,
b.port,
b.voltage_Level,
g.dict_note as voltageLevelName,
b.sequence_point ,
b.real_code ,
b.address,
d.model_name as modelName
from t_std_device a,t_std_device_attr b,t_std_metemodel d,t_dict_business e,t_dict_business f,t_dict_business g,t_dict_business h
where 1 = 1 and a.device_id = b.device_id and d.model_id=a.model_id and b.device_model = e.dict_code and b.device_vendor=f.dict_code and b.voltage_level=g.dict_code
and h.dict_code = a.device_type
 and a.device_id = #{deviceId, jdbcType=BIGINT}
 and a.custom_id = #{customId, jdbcType=VARCHAR}
 and a.device_code = #{deviceCode, jdbcType=VARCHAR}
 and a.device_name like concat('%',#{deviceName, jdbcType=VARCHAR},'%') 
 and a.alias_name = #{aliasName, jdbcType=VARCHAR}
 and a.device_type like concat('%', #{deviceType, jdbcType=INTEGER},'%')
 and a.position_type = #{positionType, jdbcType=VARCHAR}
 and a.model_id = #{modelId, jdbcType=BIGINT}
 and a.region_path = #{regionPath, jdbcType=VARCHAR}
 and a.up_region_id = #{upRegionId, jdbcType=BIGINT}
