 and a.create_time = #{createTime, jdbcType=TIMESTAMP}
 and b.device_model = #{deviceModel, jdbcType=INTEGER}
 and b.pms_type = #{pmsType, jdbcType=VARCHAR}
 and b.pms_id = #{pmsId, jdbcType=VARCHAR}
 and b.device_vendor = #{deviceVendor, jdbcType=VARCHAR}
 and b.production_date = #{productionDate, jdbcType=TIMESTAMP}
 and b.used_time = #{usedTime, jdbcType=TIMESTAMP}
 and b.disable_date = #{disableDate, jdbcType=TIMESTAMP}
 and b.last_maintenance = #{lastMaintenance, jdbcType=TIMESTAMP}
 and b.maintenance_count = #{maintenanceCount, jdbcType=VARCHAR}
 and b.organization = #{organization, jdbcType=VARCHAR}
 and b.department = #{department, jdbcType=VARCHAR}
 and b.responsible_person = #{responsiblePerson, jdbcType=VARCHAR}
 and b.latitude = #{latitude, jdbcType=VARCHAR}
